-- HCM 2.1 seed: mirror demo MDMS config records missing on tenant mz.
-- adminSchema (11) incl boundaryWithTarget.POLIO/boundary.Bednet — needed for POLIO/Bednet campaign template gen.
-- ChecklistTemplates (8) for active campaign types. Idempotent. Requires mdms-v2 restart.


SELECT schemacode, count(*) FILTER (WHERE isactive) FROM eg_mdms_data WHERE tenantid='mz' AND schemacode IN ('HCM-ADMIN-CONSOLE.adminSchema','HCM-ADMIN-CONSOLE.ChecklistTemplates') GROUP BY schemacode;
